contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        uint64 numberBefore = c.number();
        uint64 timestampBefore = c.timestamp();
        uint256 basefeeBefore = c.basefee();
        bytes32 hashBefore = c.hash();
        uint64 seqBefore = c.sequenceNumber();
        bytes32 batcherBefore = c.batcherHash();
        uint256 overheadBefore = c.l1FeeOverhead();
        uint256 scalarBefore = c.l1FeeScalar();

        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted
            && c.number() == numberBefore
            && c.timestamp() == timestampBefore
            && c.basefee() == basefeeBefore
            && c.hash() == hashBefore
            && c.sequenceNumber() == seqBefore
            && c.batcherHash() == batcherBefore
            && c.l1FeeOverhead() == overheadBefore
            && c.l1FeeScalar() == scalarBefore
        );
    }

    receive() external payable {}
}

