        bytes32 h = keccak256(abi.encodePacked(v1));
        // touch state via a reverting call using input parameters (harmless setup)
        bool reverted;
        try c.setL1BlockValues(uint64(x), uint64(x), x, bytes32(x), uint64(x), bytes32(x), x, x) { reverted = false; } catch { reverted = true; }
        string memory v2 = c.version();
        assert(reverted && keccak256(abi.encodePacked(v1)) == h && keccak256(abi.encodePacked(v2)) == h && keccak256(bytes(v2)) == keccak256(bytes("1.0.0")));
    }
    receive() external payable {}
}
